contract InvMutTest {
    C c;
    address payable selfPayable;

    constructor(C _c) {
        c = _c;
        selfPayable = payable(address(this));
    }

    // params: depositor sends 'depositAmt' to c (via this contract calling with value),
    // then attempts to Collect 'collectAmt'. We assert that if Collect succeeded,
    // the contract balance for this caller decreased by collectAmt and this contract
    // received collectAmt more Ether from c.
    function run(uint depositAmt, uint collectAmt) public payable {
        require(address(this).balance >= depositAmt, "insufficient test balance for deposit");

        // 1) Ensure MinSum is set low so the Collect condition can be met if depositAmt >= collectAmt
        // We can call SetMinSum only before c.Initialized(); tests may set any value.
        // It's an external call that may revert if already initialized, but c is fresh so it will succeed.
        c.SetMinSum(0);

        // 2) Deposit depositAmt into c from this contract
        c.Deposit{value: depositAmt}();

        // Read balance before Collect
        uint beforeBalance = c.balances(address(this));
        // Sanity: beforeBalance should equal depositAmt (the deposit increases mapping)
        // but we don't assert that; we only use beforeBalance in the invariant.

        // Record Ether balance of this test contract before attempting Collect
        uint beforeEth = address(this).balance;

        // 3) Try to Collect collectAmt and record whether it reverted
        bool reverted;
        try c.Collect(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read balance after Collect
        uint afterBalance = c.balances(address(this));
        uint afterEth = address(this).balance;

        // If Collect did not revert then:
        // - the mapping balance must have decreased by exactly collectAmt
        // - this contract's Ether balance must have increased by exactly collectAmt
        // We express that as a single general assertion over parameters and reads.
        assert(reverted || (beforeBalance >= collectAmt && afterBalance + collectAmt == beforeBalance && afterEth == beforeEth + collectAmt));
    }

    // allow receiving Ether when c sends funds back
    receive() external payable {}
 }

